"""Dependency-free Ingress UI using the Agent Control Plane visual language."""

ADMIN_CSS = r"""
:root{color-scheme:light;--bg:#f3f6f9;--surface:#fff;--surface2:#edf3f7;--text:#17243a;--muted:#687b90;--line:#d8e2eb;--cyan:#058caf;--cyan-soft:#dff5fa;--good:#16845b;--shadow:0 5px 22px #1e3a5f12}
html[data-theme=dark]{color-scheme:dark;--bg:#0d1420;--surface:#172235;--surface2:#202c41;--text:#e7edf5;--muted:#a4b2c6;--line:#30415d;--cyan:#52c9e6;--cyan-soft:#173b4a;--good:#50c895;--shadow:none}
*{box-sizing:border-box}[hidden]{display:none!important}body{font:15px system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;background:var(--bg);color:var(--text);margin:0}.app{max-width:1400px;margin:auto;padding:22px clamp(18px,2.8vw,48px) 40px}.site-header{margin-bottom:28px}.header-main{display:flex;align-items:center;gap:20px;min-height:58px}.brand{display:flex;align-items:center;gap:11px;color:var(--cyan);text-decoration:none;font-size:24px;font-weight:800;letter-spacing:-.02em}.brand img{width:46px;height:46px;object-fit:contain;filter:drop-shadow(0 4px 8px #102a4330)}.brand b{font-size:13px;color:var(--muted);font-weight:650;white-space:nowrap}.header-actions{display:flex;gap:8px;margin-left:auto}.switch{color:var(--text);padding:9px 12px;border-radius:7px;border:1px solid var(--line);background:var(--surface);font:inherit;cursor:pointer}.nav-scroll{margin-top:12px;overflow-x:auto}.nav{display:flex;gap:5px;width:max-content;min-width:100%}.nav a{color:var(--text);text-decoration:none;padding:9px 12px;border-radius:7px}.nav a.active{background:var(--cyan-soft);color:var(--cyan);font-weight:700}.view{display:none}.view.active{display:block}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:24px;align-items:center;margin:4px 0 20px}.hero h1,.pagehead h1{font-size:29px;margin:0 0 5px;letter-spacing:-.025em}.hero p,.pagehead p{margin:0;color:var(--muted)}.health{display:flex;align-items:center;gap:8px;color:var(--good);font-weight:700;background:var(--surface);border:1px solid var(--line);border-radius:10px;padding:11px 14px;box-shadow:var(--shadow)}.health i{width:9px;height:9px;border-radius:50%;background:currentColor;box-shadow:0 0 0 4px color-mix(in srgb,currentColor 15%,transparent)}.metrics{display:grid;grid-template-columns:repeat(3,minmax(150px,1fr));gap:12px}.card,.metric{background:var(--surface);border:1px solid var(--line);border-radius:12px;padding:18px;box-shadow:var(--shadow)}.metric{position:relative;overflow:hidden}.metric:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--cyan)}.metric strong{display:block;font-size:25px;line-height:1.2}.metric span,.metric small{display:block;color:var(--muted);margin-top:5px}.notice{margin-top:16px}.notice h2{font-size:19px;margin:0 0 7px}.notice p{margin:0;color:var(--muted);line-height:1.5}.pagehead{margin:4px 0 20px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;white-space:nowrap}th,td{text-align:left;padding:11px 12px;border-bottom:1px solid var(--line)}th{font-size:12px;color:var(--muted);background:var(--surface2)}tr:last-child td{border:0}.state{display:inline-block;padding:3px 8px;border-radius:999px;background:var(--cyan-soft);color:var(--good);font-size:12px}.empty{text-align:center;padding:42px;color:var(--muted)}.pager{display:flex;justify-content:flex-end;align-items:center;gap:10px;margin-top:14px}.pager button{color:var(--text);background:var(--surface2);border:1px solid var(--line);border-radius:7px;padding:8px 11px;cursor:pointer}.pager button:disabled{opacity:.5;cursor:not-allowed}.technical{font:12px ui-monospace,SFMono-Regular,Consolas,monospace;color:var(--muted)}
@media(max-width:850px){.app{padding:16px}.nav-scroll{margin-inline:-16px;padding-inline:16px}.hero{grid-template-columns:1fr}.health{justify-self:start}.metrics{grid-template-columns:1fr}}@media(max-width:560px){.brand{font-size:19px}.brand img{width:40px;height:40px}.header-main{align-items:flex-start}.header-actions{flex-direction:column}.hero h1{font-size:25px}}
"""

ADMIN_JS = r"""
const root=document.querySelector('main'),base=root.dataset.base;
const I18N={fr:{overview:'Vue d’ensemble',activity:'Activité',overviewTitle:'Vue d’ensemble',overviewIntro:'Consultez l’état opérationnel du moteur d’exécution.',operational:'Service opérationnel',appState:'Application',engineState:'Moteur',apiState:'API autonome',ready:'Prête',idle:'Inactif',shell:'Santé uniquement',lotTitle:'Fondation du Lot 0',lotText:'Aucun modèle, aucune connexion ACP et aucune exécution ne sont configurés dans ce lot.',activityTitle:'Activité',activityIntro:'Journal opérationnel persistant, limité aux métadonnées non sensibles.',date:'Date',event:'Événement',category:'Catégorie',status:'État',source:'Source',previous:'Précédent',next:'Suivant',empty:'Aucune activité enregistrée.',app_started:'Application démarrée',app_ready:'Application prête',system:'Système',success:'Succès',changeLanguage:'Changer de langue',changeTheme:'Changer de thème'},en:{overview:'Overview',activity:'Activity',overviewTitle:'Overview',overviewIntro:'Review the execution engine operational state.',operational:'Service operational',appState:'Application',engineState:'Engine',apiState:'Standalone API',ready:'Ready',idle:'Idle',shell:'Health only',lotTitle:'Lot 0 foundation',lotText:'No model, ACP connection, or execution is configured in this lot.',activityTitle:'Activity',activityIntro:'Persistent operational journal limited to non-sensitive metadata.',date:'Date',event:'Event',category:'Category',status:'Status',source:'Source',previous:'Previous',next:'Next',empty:'No activity recorded.',app_started:'Application started',app_ready:'Application ready',system:'System',success:'Success',changeLanguage:'Change language',changeTheme:'Change theme'}};
const supported=['fr','en'],saved=localStorage.getItem('aep-language'),browser=(navigator.language||'fr').slice(0,2);let language=supported.includes(saved)?saved:(supported.includes(browser)?browser:'fr');
const savedTheme=localStorage.getItem('aep-theme');let theme=['light','dark'].includes(savedTheme)?savedTheme:(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');let offset=0,total=0;
function tr(key){return I18N[language][key]||key}function apply(){document.documentElement.lang=language;document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-i18n]').forEach(e=>e.textContent=tr(e.dataset.i18n));document.getElementById('language').textContent=language==='fr'?'EN':'FR';document.getElementById('language').ariaLabel=tr('changeLanguage');document.getElementById('theme').textContent=theme==='dark'?'☀':'☾';document.getElementById('theme').ariaLabel=tr('changeTheme');renderRows(window.activityEntries||[])}
function selectView(){const view=location.hash==='#activity'?'activity':'overview';document.querySelectorAll('.view').forEach(e=>e.classList.toggle('active',e.id===view));document.querySelectorAll('.nav a').forEach(e=>e.classList.toggle('active',e.dataset.view===view));if(view==='activity')loadActivity()}
function escapeText(value){const node=document.createElement('span');node.textContent=value??'—';return node.innerHTML}function renderRows(entries){window.activityEntries=entries;const body=document.getElementById('activity-rows');if(!body)return;if(!entries.length){body.innerHTML=`<tr><td colspan="5" class="empty">${escapeText(tr('empty'))}</td></tr>`;return}body.innerHTML=entries.map(item=>`<tr><td>${escapeText(new Intl.DateTimeFormat(language,{dateStyle:'short',timeStyle:'medium'}).format(new Date(item.occurred_at)))}</td><td>${escapeText(tr(item.event_code))}<br><span class="technical">${escapeText(item.event_code)}</span></td><td>${escapeText(tr(item.category))}</td><td><span class="state">${escapeText(tr(item.status))}</span></td><td>${escapeText(item.source_ip||'—')}</td></tr>`).join('');}
async function loadActivity(){const response=await fetch(`${base}/admin/api/v1/activity?limit=50&offset=${offset}`);if(!response.ok)return;const data=await response.json();total=data.total;renderRows(data.entries);document.getElementById('previous').disabled=offset===0;document.getElementById('next').disabled=offset+data.entries.length>=total;}
document.getElementById('language').onclick=()=>{language=language==='fr'?'en':'fr';localStorage.setItem('aep-language',language);apply()};document.getElementById('theme').onclick=()=>{theme=theme==='dark'?'light':'dark';localStorage.setItem('aep-theme',theme);apply()};document.getElementById('previous').onclick=()=>{offset=Math.max(0,offset-50);loadActivity()};document.getElementById('next').onclick=()=>{offset+=50;loadActivity()};addEventListener('hashchange',selectView);apply();selectView();
"""
